import { HonoRequest } from '../clone/src/request'

const form = new FormData()
form.append('a', '1')
const raw = new Request('http://localhost/', { method: 'POST', body: form })
const request = new HonoRequest(raw)
console.log('formData:', (await request.formData()).get('a'))
try {
  console.log('parseBody:', await request.parseBody())
} catch (error) {
  console.log('parseBody after formData threw:', error.message, '-', error.cause?.message)
}
